```javascript
const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').split(/\r?\n/);

// Normaliza removendo acentos (precaução: enunciado garante letras sem acento,
// mas um dos exemplos contém acento — isso trata ambos os casos corretamente)
const strip = (s) => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();

const P = strip(input[0] || '');
const A = strip(input[1] || '');

// Conta frequência das letras de P
const freq = new Map();
for (const ch of P) freq.set(ch, (freq.get(ch) || 0) + 1);

// A é anagrama curinga de P sse:
// - mesmos comprimentos (garantido, mas verificado por segurança)
// - para cada letra de A (não '*'), ela pode ser casada com uma letra distinta de P
// (os '*' casam automaticamente com as letras restantes de P)
let ok = P.length === A.length;
for (const ch of A) {
  if (!ok) break;
  if (ch === '*') continue;
  const c = freq.get(ch) || 0;
  if (c === 0) {
    ok = false;
    break;
  }
  freq.set(ch, c - 1);
}

console.log(ok ? 'S' : 'N');
